import json,numpy as np
from scipy.spatial.transform import Rotation
from pathlib import Path
from gen import *

def target_pixels(im):
    import scipy.ndimage as ndi
    m=(im[:,:,0].astype(float)>50)&(im[:,:,0]>1.7*im[:,:,1].astype(float))&(im[:,:,0]>1.7*im[:,:,2].astype(float))
    labs,n=ndi.label(m)
    counts=np.bincount(labs.ravel());counts[0]=0
    m=labs==counts.argmax(); y,x=np.where(m)
    return [x.mean(), y.mean()], [x.min(),y.min(),x.max(),y.max()]

def rotq(q,axis,p):
    R=Rotation.from_rotvec(np.array(axis)*q).as_matrix()
    T=np.eye(4);T[:3,:3]=R;T[:3,3]=np.array(p)-R@np.array(p)
    return T

class Model:
    def __init__(self,s):
        self.s=s;self.names=s['links']['names'];self.parents=s['links']['parent'];self.act=s['proprio']['joints']
    def transforms(self,q):
        ts={'pelvis':np.eye(4)}
        for name,par in zip(self.names[1:],self.parents[1:]):
            j=name.removesuffix('_link')
            if j in self.act:
                i=self.act.index(j);ts[name]=ts[par]@rotq(q[i],self.s['proprio']['axis'][i],self.s['proprio']['position_m'][i])
            else:ts[name]=ts[par]
        return ts
    def points(self,q):
        ts=self.transforms(q)
        return {name:(ts[name]@np.r_[p,1])[:3] for name,p in zip(self.names,self.s['links']['com_m'])}
    def hand(self,q):return self.points(q)['left_hand']

def stereo(z):
    pix=[target_pixels(z.last[c])[0] for c in ['left_eye_camera','right_eye_camera']]
    f=128/np.tan(np.pi/8);dis=pix[0][0]-pix[1][0]
    X=f*.06/dis; Y=-(np.mean([p[0] for p in pix])-127.5)*X/f; Z=-(np.mean([p[1] for p in pix])-127.5)*X/f
    return np.array([X,Y,Z]),pix

if __name__=='__main__':
 r=connect();z=observe(r,'current');s=r.spec();q=np.array(z.meta['proprio']['now'][:19]);m=Model(s)
 print('pixel',[(c,target_pixels(im)) for c,im in z.last.items()]);print('stereo',stereo(z));
 print('hand',m.hand(q));print('com',sum(v*mass for v,mass in zip(m.points(q).values(),s['links']['mass_kg']))/sum(s['links']['mass_kg']))
 ts=m.transforms(q);p,pix=stereo(z);p=ts['torso_link']@np.r_[p+np.array([.1,0,.65]),1];print('target pelvis',p)
