def replay_recorded_commands():
    """Replay the camera-guided command sequence on the running episode, without reset."""
    r=connect()
    records=[json.loads(line) for line in (OUT/'actions.jsonl').read_text().splitlines()]
    ranges=np.array(r.spec()['action_types']['joint_position']['range_rad'])
    for rec in records:
        if r.status()['done']:
            break
        if rec.get('ramp'):
            qs=np.linspace(rec['start'],rec['q_rad'],rec['steps'])
        else:
            qs=np.tile(rec['q_rad'],(rec['steps'],1))
        aa=np.clip(2*(qs-ranges[:,0])/(ranges[:,1]-ranges[:,0])-1,-1,1)
        z=r.submit('joint_position',aa,video='none',note=rec['label'])
        z.save(OUT/('replay_'+rec['label']))
    print(json.dumps(r.status(),indent=2))

if __name__ == '__main__':
    replay_recorded_commands()
